//! False positives are possible for non-System classes using similar method names.
//!
//! ## Layout
//!
//! The per-check `check_*` methods and their tests live in sibling `check_*.rs`
//! modules in this directory. This module keeps the engine, the dispatch, the
//! file-level class traversal, and the shared free helpers.

#[cfg(test)]
pub(crate) mod test_support {
    use super::*;
    use mlt_core::Config;

    /// Build a `SystemObjectsEngine` with default configuration for tests.
    pub(crate) fn engine() -> Box<dyn Rule> {
        SystemObjectsEngine::from_config(&Config::default())
    }

    /// Wrap a class body in a `matlab.System` class definition.
    pub(crate) fn system_class(source: &str) -> String {
        format!(
            "classdef mySystem < matlab.System\n{}\nend\n",
            source
        )
    }
}

